+                if (!storeCreationAllowed || integrityMode == IntegrityMode.FAIL) {
+                    throw creationDisabled(storedRulesFile);
+                }
+                try {
+                    Files.createFile(index);
+                } catch (FileAlreadyExistsException ignored) {
+                    // Another initializer won the race. The regular-file check below is authoritative.
+                }
+            }
+            if (!Files.isRegularFile(index, LinkOption.NOFOLLOW_LINKS)) {
+                throw new StoreInitializationFailedException(String.format(
