+    private boolean isSharedWithAnotherEntry(String description, String fileName, Path file) {
+        for (Map.Entry<String, String> entry : storedRules.entries().entrySet()) {
+            if (entry.getKey().equals(description)) {
+                continue;
+            }
+            if (entry.getValue().equals(fileName)) {
+                return true;
+            }
+            try {
+                if (sameFileIfPossible(file, pathFor(entry.getValue()))) {
