+    private void writeRuleFile(Path target, byte[] contents) {
+        try {
+            Files.write(target, contents, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);
+        } catch (IOException | InvalidPathException e) {
+            throw new StoreUpdateFailedException(e);
+        }
