+    private byte[] serializeViolations(List<String> violations) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append('\n');
+        }
+        return builder.toString().getBytes(UTF_8);
+    }
+
+    private String escape(String violation) {
+        StringBuilder result = new StringBuilder(violation.length() + 8);
+        for (int i = 0; i < violation.length(); i++) {
+            char c = violation.charAt(i);
+            if (c == '\r' || c == '\n') {
+                result.append('\\');
+            }
+            result.append(c);
+        }
+        return result.toString();
+    }
