+    private List<String> readLines(String ruleDetailsFileName) {
+        String violationsText = readStoreFile(ruleDetailsFileName);
+        if (isOnlyLineBreaks(violationsText)) {
+            return Collections.emptyList();
+        }
+        List<String> result = new ArrayList<>();
+        StringBuilder current = new StringBuilder();
+        for (int i = 0; i < violationsText.length(); i++) {
+            char c = violationsText.charAt(i);
+            boolean escaped = i > 0 && violationsText.charAt(i - 1) == '\\';
+            if (c == '\n' && !escaped) {
+                if (current.length() > 0) {
+                    result.add(current.toString());
+                }
+                current.setLength(0);
+            } else if (c == '\r' && i + 1 < violationsText.length() && violationsText.charAt(i + 1) == '\n' && !escaped) {
+                if (current.length() > 0) {
+                    result.add(current.toString());
+                }
+                current.setLength(0);
+                i++;
+            } else if (escaped && (c == '\r' || c == '\n')) {
+                current.setLength(current.length() - 1);
+                current.append(c);
+            } else {
+                current.append(c);
+            }
+        }
+        if (current.length() > 0) {
+            result.add(current.toString());
+        }
+        return result;
+    }
+
+    private boolean isOnlyLineBreaks(String text) {
+        if (text.isEmpty()) {
+            return true;
+        }
+        for (int i = 0; i < text.length(); i++) {
+            char c = text.charAt(i);
+            if (c == '\n') {
+                continue;
+            }
+            if (c == '\r') {
+                if (i + 1 < text.length() && text.charAt(i + 1) == '\n') {
+                    i++;
+                }
+                continue;
+            }
+            return false;
+        }
+        return true;
+    }
