+    private boolean targetExists(Path path) {
+        return Files.exists(path, LinkOption.NOFOLLOW_LINKS);
+    }
+
+    private boolean sameFileIfPossible(Path first, Path second) throws IOException {
+        if (!targetExists(first) || !targetExists(second)) {
+            return false;
+        }
+        return Files.isSameFile(first, second);
+    }
+
+    private void deleteNamedFile(Path path) throws IOException {
+        if (!targetExists(path)) {
+            return;
+        }
+        if (Files.isSymbolicLink(path)) {
+            Path target = path.toRealPath();
+            Files.delete(target);
+            Files.deleteIfExists(path);
+        } else {
+            Files.delete(path);
+        }
+    }
