+    private IntegrityState inspectIntegrity() {
+        Map<String, Entry> entries = new HashMap<>();
+        for (Map.Entry<String, String> indexEntry : storedRules.entries().entrySet()) {
+            Entry entry = new Entry(indexEntry.getKey(), indexEntry.getValue());
+            entry.path = resolve(entry.fileName);
+            entry.broken = entry.path.broken || isIndex(entry.path);
+            entry.resolved = !entry.broken && isResolved(entry.path.path);
+            if (!randomFileNames) {
+                entry.derivedFileName = requireFileName(entry.description);
+            } else {
+                entry.derivedFileName = entry.fileName;
+            }
+            entry.misplaced = !entry.fileName.equals(entry.derivedFileName);
+            entries.put(entry.description, entry);
+        }
+
+        List<Entry> allEntries = new ArrayList<>(entries.values());
+        for (Entry entry : allEntries) {
+            for (Entry other : allEntries) {
+                if (entry == other) {
+                    continue;
+                }
+                if (entry.fileName.equals(other.fileName) || reachesSameFile(entry.path, other.path)) {
