public class TextFileBasedViolationStoreConcurrencyTest {

    @TempDir
    Path temporaryFolder;

    private File configuredFolder;

    @BeforeEach
    public void setUp() {
        configuredFolder = new File(temporaryFolder.toFile(), "notyetthere");
